"use strict";

module.exports = async function promisePoolProbe(values) {
  const scheduled = values.map((value) => Promise.resolve()
    .then(() => new Promise((resolve) => setTimeout(resolve, 0, value * value))));
  const squares = await Promise.all(scheduled);
  const sum = squares.reduce((acc, value) => acc + value, 0);
  return {
    sum,
    summary: `concurrency:pool/${sum}/${squares.length}`,
  };
};
